import json,re,html,collections,xml.etree.ElementTree as ET
from pathlib import Path
s=json.loads(Path('source.json').read_text()); a=json.loads(Path('answer.json').read_text())
def plain(x):
 return html.unescape(re.sub('<["'^>]+>'"', '', x))
allowed={'p','br','table','thead','tbody','tfoot','tr','th','td','b','strong','i','em','u','sup','sub','ul','ol','li','div','span','blockquote'}
classes={'material_reduction','coordination_only','retained_necessary','financing_transfer','payment_timing_relief','mixed','reserved','editorial_only'}
kinds={'tax_removed','tax_reduced','obligation_removed','obligation_merged','authorization_removed','regime_merged','deadline_reduced','compliance_cost_reduced','tax_increased','obligation_added','deadline_increased','complexity_added','financing_transfer','payment_deferred','relief_extended','relief_preserved','coordination'}
units={'percent','euro','legal_duty','regime','calendar_days','working_days','financing','other'}
assert len(a)==len(s)==24
for src,out in zip(s,a):
 for key in ['code_id','source_id','source_sha256','number']: assert src[key]==out[key],(src['number'],key)
 for key in ['reason','review_notes']:assert out[key].strip()
 impact=out['substantive_impact'];assert impact['version']==1 and impact['classification'] in classes
 for key in ['assessment','scope_limitations','new_burdens_review']:assert len(impact[key])>=40
 if src.get('benefit_check_required'):assert len(out['benefit_review'])>=100
 if out['status']=='retained_unchanged':
  assert out['proposed_xml'] is None and out['classification']=='retained_necessary'
  assert impact['classification']=='retained_necessary' and impact['effects']==[]
 else:
  assert out['status']=='rewrite_draft' and isinstance(out['proposed_xml'],str)
  root=ET.fromstring('<root>'+out['proposed_xml']+'</root>')
  for el in list(root.iter())[1:]:
   assert el.tag in allowed,(src['number'],el.tag)
   for k,v in el.attrib.items(): assert k in {'rowspan','colspan'} and v.isdigit()
  if out.get('change_type')=='normative_reduction':
   assert out['reform_policy_id']=='editorial_direction_2026_10_19'
   assert out['removed_provisions'] and all(len(t)>=30 for t in out['removed_provisions'])
 for e in impact['effects']:
  assert e['kind'] in kinds and e['unit'] in units
  assert re.fullmatch('[a-z0-9]+(?:-[a-z0-9]+)*',e['measure_id']) and 6<=len(e['measure_id'])<=96
  for key in ['description','before','after','affected_population','conditions_and_transition','replacement_or_new_burdens']: assert e[key].strip()
  for key,body in [('source_quote',src['source_xml']),('proposed_quote',out['proposed_xml'])]:
   assert len(e[key])>=12 and e[key] in plain(body),(src['number'],key,e[key])
print('24 objets ; identifiants, statuts, XML, analyses et citations vérifiés.')
print('Statuts :',dict(collections.Counter(x['status'] for x in a)))
print('Impacts :',dict(collections.Counter(x['substantive_impact']['classification'] for x in a)))
print('Effets :',dict(collections.Counter(e['kind'] for x in a for e in x['substantive_impact']['effects'])))
print('Taille answer.json :',Path('answer.json').stat().st_size,'octets')
for src,out in zip(s,a):
 if out['proposed_xml'] is not None:
  print('\\nARTICLE',src['number'],'\\nSOURCE\\n'+src['source_xml']+'\\nPROPOSITION\\n'+out['proposed_xml'])
PY"

